CREATE TABLE users(id text PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE TABLE guest_identities(id uuid PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),merged_into text REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_profiles(user_id text PRIMARY KEY REFERENCES users(id),display_name text,age_band text,locale text NOT NULL DEFAULT 'zh-CN',preferences jsonb NOT NULL DEFAULT '{}');
CREATE TABLE character_threads(id uuid PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),character_id text NOT NULL,character_version text NOT NULL,current_epoch_id uuid,title text NOT NULL,summary text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,character_id));
CREATE TABLE thread_epochs(id uuid PRIMARY KEY,thread_id uuid NOT NULL REFERENCES character_threads(id) ON DELETE CASCADE,character_version text NOT NULL,started_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz);
ALTER TABLE character_threads ADD CONSTRAINT character_threads_epoch_fk FOREIGN KEY(current_epoch_id) REFERENCES thread_epochs(id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE messages(id uuid PRIMARY KEY,thread_id uuid NOT NULL REFERENCES character_threads(id) ON DELETE CASCADE,epoch_id uuid NOT NULL REFERENCES thread_epochs(id),role text NOT NULL,content text NOT NULL,character_version text NOT NULL,claim_ids jsonb NOT NULL DEFAULT '[]',citations jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX messages_thread_created_idx ON messages(thread_id,created_at,id);
CREATE TABLE memories(id uuid PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),character_id text,type text NOT NULL,content text NOT NULL,embedding vector(1536),confidence real NOT NULL,importance real NOT NULL,sensitivity text NOT NULL,status text NOT NULL,recall_count int NOT NULL DEFAULT 0,last_recalled_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memory_sources(memory_id uuid NOT NULL REFERENCES memories(id) ON DELETE CASCADE,message_id uuid NOT NULL REFERENCES messages(id) ON DELETE CASCADE,PRIMARY KEY(memory_id,message_id));
CREATE INDEX memories_scope_idx ON memories(user_id,character_id,status);
CREATE TABLE mastery_topics(id uuid PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),topic_id text NOT NULL,level text NOT NULL,confidence real NOT NULL,last_practiced_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,topic_id));
CREATE TABLE mastery_evidence(mastery_id uuid NOT NULL REFERENCES mastery_topics(id) ON DELETE CASCADE,message_id uuid NOT NULL REFERENCES messages(id) ON DELETE CASCADE,kind text NOT NULL DEFAULT 'exposure',created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(mastery_id,message_id));
CREATE TABLE consents(id uuid PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),type text NOT NULL,scope jsonb NOT NULL,status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz);
CREATE TABLE agent_tasks(id uuid PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),type text NOT NULL,status text NOT NULL,input jsonb NOT NULL,plan jsonb NOT NULL,current_step int NOT NULL DEFAULT 0,provider text NOT NULL,model text NOT NULL,attempt int NOT NULL DEFAULT 0,consent_id uuid REFERENCES consents(id),resume_token uuid NOT NULL,error_code text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE agent_artifacts(id uuid PRIMARY KEY,task_id uuid NOT NULL REFERENCES agent_tasks(id) ON DELETE CASCADE,kind text NOT NULL,name text NOT NULL,content_type text NOT NULL,data jsonb,storage_key text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE agent_steps(id uuid PRIMARY KEY,task_id uuid NOT NULL REFERENCES agent_tasks(id) ON DELETE CASCADE,name text NOT NULL,status text NOT NULL,tool text,detail text,started_at timestamptz,completed_at timestamptz);
